    private void launch()throws Exception{player=null;activity=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));await(()->{player=(PlaybackService)field(activity,"player");return player!=null;},10000,"Bind native player");}
    private void shutdown()throws Exception{if(activity==null||activity.isDestroyed())return;PlaybackService previous=player;onMain(()->{if(previous!=null)previous.stopPlayback();activity.finish();});await(()->activity.isDestroyed()&&(previous==null||(Boolean)field(previous,"destroyed")),8000,"Release native service");waitForIdleSync();}
    private void configure(boolean enabled,double preamp,double echo,double reverb,boolean norm,double[] gains)throws Exception{onMain(()->player.pause());store.importProfile(profile(enabled,preamp,echo,reverb,norm,gains).toString(),true);onMain(()->player.reloadSettings());}
    private JSONObject profile(boolean enabled,double preamp,double echo,double reverb,boolean norm,double[] gains)throws Exception{JSONObject value=PortableProfile.normalize(new JSONObject().put("format","lolzcloud-profile").put("version",1)),sound=value.getJSONObject("music").getJSONObject("dsp");JSONArray curve=new JSONArray();for(double gain:gains)curve.put(gain);sound.put("enabled",enabled).put("preampDb",preamp).put("echo",echo).put("reverb",reverb).put("gains",curve).put("rate",1).put("preservesPitch",true);value.getJSONObject("tools").put("normalization",norm);return value;}
    private void start(List<Track> queue,int index,boolean play)throws Exception{onMain(()->{player.setRepeat(0);player.setShuffle(false);player.setQueue(queue,index,play);});await(()->player.isPrepared(),160000,"Prepare production PCM");onMain(()->{});if(play)await(()->player.isPlaying(),5000,"Start production AudioTrack");}
    private boolean steady(long frames){PcmPlayback.Snapshot value=player.pcmSnapshot();return value!=null&&value.steadyFrames>=frames&&value.appliedRevision==value.requestedRevision&&player.isPlaying();}
    private PcmPlayback.Snapshot record(String name)throws Exception{PcmPlayback.Snapshot value=player.pcmSnapshot();if(value==null)throw new AssertionError("No real PCM renderer");meters.put(json(name,value));return value;}
    private JSONObject json(String name,PcmPlayback.Snapshot value)throws Exception{JSONArray buckets=new JSONArray();for(double energy:value.outputBuckets)buckets.put(energy);return new JSONObject().put("case",name).put("state",value.state).put("requestedRevision",value.requestedRevision).put("appliedRevision",value.appliedRevision).put("acceptedFrames",value.acceptedFrames).put("playedFrames",value.playedFrames).put("steadyFrames",value.steadyFrames).put("sampleRate",value.sampleRate).put("channels",value.channels).put("audioSession",value.audioSession).put("outputEncoding",value.outputEncoding).put("inputRms",value.inputRms).put("outputRms",value.outputRms).put("peak",value.peak).put("silentOutputEnergy",value.silentOutputEnergy).put("normalizationDb",value.normalizationDb).put("normalizationMeasured",value.normalizationMeasured).put("loudness",Double.isFinite(value.loudness)?value.loudness:JSONObject.NULL).put("speed",value.speed).put("pitch",value.pitch).put("volume",value.volume).put("outputEnergy100msBuckets",buckets);}
    private Track wave(String name,double frequency,double amplitude,double seconds,boolean impulse)throws Exception{File file=new File(fixtures,name+".wav");int frames=(int)Math.round(48000*seconds),bytes=frames*4;try(OutputStream out=new BufferedOutputStream(new FileOutputStream(file))){out.write("RIFF".getBytes("US-ASCII"));le(out,bytes+36,4);out.write("WAVEfmt ".getBytes("US-ASCII"));le(out,16,4);le(out,1,2);le(out,2,2);le(out,48000,4);le(out,192000,4);le(out,4,2);le(out,16,2);out.write("data".getBytes("US-ASCII"));le(out,bytes,4);for(int i=0;i<frames;i++){short sample=(short)Math.round((impulse&&i>240?0:amplitude*Math.sin(2*Math.PI*frequency*i/48000))*32767);le(out,sample,2);le(out,sample,2);}}Track row=new Track("pcm-qa-"+name,"PCM "+name,"Generated PCM QA",Uri.fromFile(file).toString(),Math.round(seconds*1000));store.add(row);return row;}
    private Set<String> compressedCache(){Set<String> files=new HashSet<>();String[] names=getTargetContext().getCacheDir().list();if(names!=null)for(String name:names)if(name.matches("pcm-source-.*\\.audio"))files.add(name);return files;}
    private void networkReady()throws Exception{ConnectivityManager manager=(ConnectivityManager)getTargetContext().getSystemService(Context.CONNECTIVITY_SERVICE);await(()->{NetworkCapabilities cap=manager.getNetworkCapabilities(manager.getActiveNetwork());return cap!=null&&cap.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED);},15000,"Validated network for public catalog fixture");}
    private void await(Condition condition,long timeout,String message)throws Exception{long end=SystemClock.elapsedRealtime()+timeout;while(!condition.ready()){if(!cleaning&&player!=null&&!player.error().isEmpty())throw new AssertionError(message+": "+player.error());if(SystemClock.elapsedRealtime()>end)throw new AssertionError(message);SystemClock.sleep(30);}}
    private void check(boolean value,String message)throws Exception{if(!value)throw new AssertionError(message);checks.put(message);write("progress.json",new JSONObject().put("checks",checks).toString());}
    private void onMain(Task task)throws Exception{Throwable[] failure={null};runOnMainSync(()->{try{task.run();}catch(Throwable error){failure[0]=error;}});if(failure[0] instanceof Error)throw(Error)failure[0];if(failure[0]!=null)throw(Exception)failure[0];}
    private static Object field(Object target,String name)throws Exception{Field field=target.getClass().getDeclaredField(name);field.setAccessible(true);return field.get(target);}
    private String shell(String command)throws IOException{try(InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(getUiAutomation().executeShellCommand(command));ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] bytes=new byte[8192];int count;while((count=in.read(bytes))!=-1)out.write(bytes,0,count);return out.toString("UTF-8");}}
    private void capture(String name)throws Exception{SystemClock.sleep(600);Bitmap screenshot=getUiAutomation().takeScreenshot();if(screenshot!=null){try(FileOutputStream out=new FileOutputStream(new File(output,name))){screenshot.compress(Bitmap.CompressFormat.PNG,100,out);}screenshot.recycle();screenshots.put(name);}}
    private void write(String name,String value)throws IOException{try(FileOutputStream out=new FileOutputStream(new File(output,name))){out.write(value.getBytes(StandardCharsets.UTF_8));}}
    private static void le(OutputStream out,int value,int count)throws IOException{for(int i=0;i<count;i++)out.write(value>>>(8*i)&255);}
    private static Map<String,Object> snapshot(SharedPreferences prefs){Map<String,Object> values=new HashMap<>();for(Map.Entry<String,?> entry:prefs.getAll().entrySet())values.put(entry.getKey(),entry.getValue() instanceof Set?new HashSet<>((Set<?>)entry.getValue()):entry.getValue());return values;}
    @SuppressWarnings("unchecked")private static void restore(SharedPreferences prefs,Map<String,Object> values)throws IOException{SharedPreferences.Editor edit=prefs.edit().clear();for(Map.Entry<String,Object> entry:values.entrySet()){Object value=entry.getValue();String key=entry.getKey();if(value instanceof String)edit.putString(key,(String)value);else if(value instanceof Boolean)edit.putBoolean(key,(Boolean)value);else if(value instanceof Integer)edit.putInt(key,(Integer)value);else if(value instanceof Long)edit.putLong(key,(Long)value);else if(value instanceof Float)edit.putFloat(key,(Float)value);else if(value instanceof Set)edit.putStringSet(key,(Set<String>)value);}if(!edit.commit())throw new IOException("Preference restoration failed");}
    private static String sha(File file)throws Exception{MessageDigest hash=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(file)){byte[] bytes=new byte[8192];int count;while((count=in.read(bytes))!=-1)hash.update(bytes,0,count);}StringBuilder value=new StringBuilder();for(byte b:hash.digest())value.append(String.format(Locale.ROOT,"%02x",b&255));return value.toString();}
